package io.github.mikeceead.xbscompanion;
import android.app.Activity;import android.app.Instrumentation;import android.content.Intent;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;import android.view.View;import android.view.ViewGroup;import android.widget.CheckBox;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import androidx.core.view.ViewCompat;
@RunWith(AndroidJUnit4.class)
public final class AccessibilityAdaptiveInstrumentedTest {
 @Test public void testProductionPolicyCoversDirectSpinnerAndCheckbox() throws Throwable {Instrumentation i=InstrumentationRegistry.getInstrumentation();final Throwable[] error=new Throwable[1];i.runOnMainSync(()->{try{UiKit ui=new UiKit(i.getTargetContext());LinearLayout root=new LinearLayout(i.getTargetContext());root.setOrientation(LinearLayout.VERTICAL);TextView title=ui.text("Representative screen",27,ui.palette.text,true);root.addView(title);Spinner spinner=new Spinner(i.getTargetContext());CheckBox check=new CheckBox(i.getTargetContext());root.addView(spinner);root.addView(check);UiQualityReport.AccessibilityResult result=AccessibilityUiPolicy.apply(i.getTargetContext(),root,"Representative screen");assertTrue(spinner.getMinimumHeight()>=ui.dp(48));assertTrue(check.getMinimumHeight()>=ui.dp(48));assertTrue(ViewCompat.isAccessibilityHeading(title));assertEquals(0,result.failures);assertTrue(result.paneReady);}catch(Throwable t){error[0]=t;}});if(error[0]!=null)throw new AssertionError(error[0]);}
 @Test public void testRepresentativeRealScreensExposeMeaningfulPaneAndHeading() throws Throwable {assertActivity(SecuritySealActivity.class,null);assertActivity(CliCommandActivity.class,Spinner.class);assertActivity(AppPickerActivity.class,CheckBox.class);}
 @Test public void testCancelActionIsDurablyOneUse() throws Throwable {Instrumentation i=InstrumentationRegistry.getInstrumentation();RuntimeNotificationStore.CancelAction action=RuntimeNotificationStore.publishCancelAction(i.getTargetContext(),"run-1");assertTrue(action.ready());assertTrue(RuntimeNotificationStore.consumeCancelAction(i.getTargetContext(),"run-1",action.nonce,action.issuedAt,action.issuedAt+1));assertFalse(RuntimeNotificationStore.consumeCancelAction(i.getTargetContext(),"run-1",action.nonce,action.issuedAt,action.issuedAt+2));}
 private void assertActivity(Class<? extends Activity> type,Class<?> requiredControl) throws Throwable {Instrumentation i=InstrumentationRegistry.getInstrumentation();Intent intent=new Intent(i.getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity activity=i.startActivitySync(intent);View root=activity.getWindow().getDecorView();long deadline=System.currentTimeMillis()+4000L;do{i.waitForIdleSync();if(requiredControl==null||containsType(root,requiredControl))break;Thread.sleep(50L);}while(System.currentTimeMillis()<deadline);CharSequence pane=findPane(root);assertNotNull(pane);assertFalse(pane.toString().trim().isEmpty());assertTrue(hasHeading(root));if(requiredControl!=null)assertTrue("missing "+requiredControl.getSimpleName(),containsType(root,requiredControl));assertTouchTargets(root,Math.round(48*i.getTargetContext().getResources().getDisplayMetrics().density));activity.finish();i.waitForIdleSync();}
 private CharSequence findPane(View v){CharSequence own=ViewCompat.getAccessibilityPaneTitle(v);if(own!=null&&!own.toString().trim().isEmpty())return own;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++){CharSequence found=findPane(g.getChildAt(n));if(found!=null)return found;}}return null;}
 private boolean hasHeading(View v){if(ViewCompat.isAccessibilityHeading(v))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++)if(hasHeading(g.getChildAt(n)))return true;}return false;}
 private boolean containsType(View v,Class<?> type){if(type.isInstance(v))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++)if(containsType(g.getChildAt(n),type))return true;}return false;}
 private void assertTouchTargets(View v,int min){if(v.isClickable()||v.isLongClickable()||v instanceof Spinner||v instanceof android.widget.CompoundButton||v instanceof android.widget.EditText){assertTrue("height "+v.getClass(),v.getMinimumHeight()>=min);assertTrue("width "+v.getClass(),v.getMinimumWidth()>=min);}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++)assertTouchTargets(g.getChildAt(n),min);}}
}
